      "support_status": "SUFFICIENT",
      "rationale": "P007 explicitly requires demonstrated feasibility; P006 identifies the selected case's replay."
    }
  },
  "signal_basis": {
    "component_id": "C008.signal_basis",
    "value": "The replay reproduces baseline failure, and a smaller configuration repeatedly remains late while specified further removals cease to reproduce lateness. Tests hold equipment, deadline and other conditions fixed, apply the same predeclared repetition rule, and classify inconsistent or uncertain outcomes as unresolved. Failure to reproduce the baseline supplies no basis for reduction.",
    "scope": "The selected late case and its tested replay configurations.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "CONTEXT"
        },
